            rule_section(:scoring, "Wszystko albo nic i zako\u0144czenie partii",
              "Domy\u015Blnie dzia\u0142a zasada \u201EWszystko albo nic\u201D: je\u017Celi zbierzesz wszystkie punktuj\u0105ce karty lub wszystkie kolejki, wynik tej rundy zmienia znak. Zamiast dopisa\u0107 kar\u0119, odejmujesz j\u0105 od wyniku. Ta zasada nie dotyczy czwartej rundy.",
              "W pierwszej rundzie musisz zebra\u0107 wszystkie karty, w drugiej wszystkie karty wybranego koloru, a w trzeciej wszystkie cztery figury wskazanego rodzaju. W pi\u0105tej i sz\u00F3stej trzeba zebra\u0107 ca\u0142\u0105 tali\u0119. W sz\u00F3stej zmiana znaku dzia\u0142a na niekorzy\u015B\u0107: zamiast odj\u0105\u0107 punkty, dopisujesz je sobie.",
              "Po sze\u015Bciu rundach wygrywa osoba z najni\u017Cszym wynikiem. R\u00F3wne najni\u017Csze wyniki oznaczaj\u0105 remis. Punktacj\u0119 sprawdzisz klawiszem S. Zasad\u0119 \u201EWszystko albo nic\u201D mo\u017Cna wy\u0142\u0105czy\u0107 w ustawieniach sto\u0142u."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ki: przegl\u0105daj karty.",
              "Enter: zagraj wybran\u0105 kart\u0119.",
              "H: odczytaj swoj\u0105 r\u0119k\u0119.",
              "C: odczytaj karty z bie\u017C\u0105cej kolejki.",
              "Ctrl+C: przejrzyj te karty.",
              "F: przypomnij kolor, do kt\u00F3rego dok\u0142adasz.",
              "R / V: przypomnij zasady bie\u017C\u0105cej rundy.",
              "S: odczytaj wyniki.",
              "T: sprawd\u017A, czyja jest tura.",
              "Z / Shift+Z: znajd\u017A nast\u0119pn\u0105 / poprzedni\u0105 kart\u0119 mo\u017Cliw\u0105 do zagrania.",
              "Shift+C: sortuj wed\u0142ug kolor\u00F3w.",
              "Shift+H: sortuj wed\u0142ug warto\u015Bci.",
              "Shift+M: przywr\u00F3\u0107 kolejno\u015B\u0107 otrzymania kart.")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 Bouillabaisse \u043C\u043E\u0433\u0443\u0442 \u0438\u0433\u0440\u0430\u0442\u044C \u043E\u0442 2 \u0434\u043E 8 \u0447\u0435\u043B\u043E\u0432\u0435\u043A. \u0417\u0430 \u0448\u0435\u0441\u0442\u044C \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u043D\u0443\u0436\u043D\u043E \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u043A\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u043C\u0435\u043D\u044C\u0448\u0435 \u043E\u0447\u043A\u043E\u0432. \u041E\u0431\u044B\u0447\u043D\u043E \u043E\u0447\u043A\u0438 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u043A\u0430\u043A \u0448\u0442\u0440\u0430\u0444 \u0437\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u0435 \u0432\u0437\u044F\u0442\u044B\u0435 \u043A\u0430\u0440\u0442\u044B, \u0430 \u0432 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u0442\u0435 \u0436\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0432\u044B\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u0438\u0437 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430."),
            rule_section(:play, "\u041A\u0430\u043A \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B",
              "\u0412\u0441\u0435\u043C \u0440\u0430\u0437\u0434\u0430\u044E\u0442 \u043F\u043E\u0440\u043E\u0432\u043D\u0443 \u043A\u0430\u0440\u0442 \u0438\u0437 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u043B\u043E\u0434\u044B. \u0415\u0441\u043B\u0438 \u043A\u043E\u043B\u043E\u0434\u0430 \u043D\u0435 \u0434\u0435\u043B\u0438\u0442\u0441\u044F \u043D\u0430 \u0447\u0438\u0441\u043B\u043E \u0438\u0433\u0440\u043E\u043A\u043E\u0432, \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u0430\u043C\u044B\u0445 \u043C\u043B\u0430\u0434\u0448\u0438\u0445 \u043A\u0430\u0440\u0442 \u0443\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F. \u041F\u0435\u0440\u0432\u043E\u0433\u043E \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E, \u0437\u0430\u0442\u0435\u043C \u0441\u0434\u0430\u0447\u0430 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443 \u0432 \u043A\u0430\u0436\u0434\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435.",
              "\u041F\u0435\u0440\u0432\u044B\u043C \u0445\u043E\u0434\u0438\u0442 \u0438\u0433\u0440\u043E\u043A \u043F\u043E\u0441\u043B\u0435 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E. \u0412\u044B\u0431\u0435\u0440\u0438 \u043A\u0430\u0440\u0442\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u0441\u044B\u0433\u0440\u0430\u0439 \u0435\u0451 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043A\u043B\u0430\u0434\u0443\u0442 \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u0435. \u0415\u0441\u043B\u0438 \u0443 \u0442\u0435\u0431\u044F \u0435\u0441\u0442\u044C \u043C\u0430\u0441\u0442\u044C \u043F\u0435\u0440\u0432\u043E\u0439 \u043A\u0430\u0440\u0442\u044B, \u043D\u0443\u0436\u043D\u043E \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u044D\u0442\u043E\u0439 \u043C\u0430\u0441\u0442\u0438; \u0438\u043D\u0430\u0447\u0435 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u0443\u044E.",
              "\u0421\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043C\u0430\u0441\u0442\u0438 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0445\u043E\u0434\u0430 \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0432\u0437\u044F\u0442\u043A\u0443, \u0438 \u0435\u0451 \u0432\u043B\u0430\u0434\u0435\u043B\u0435\u0446 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E. \u0422\u0443\u0437 \u0441\u0442\u0430\u0440\u0448\u0435 \u043A\u043E\u0440\u043E\u043B\u044F, \u0437\u0430\u0442\u0435\u043C \u0438\u0434\u0443\u0442 \u0434\u0430\u043C\u0430, \u0432\u0430\u043B\u0435\u0442, \u0434\u0435\u0441\u044F\u0442\u043A\u0430 \u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0434\u043E \u0434\u0432\u043E\u0439\u043A\u0438. \u041A\u043E\u0437\u044B\u0440\u0435\u0439 \u043D\u0435\u0442. \u041A\u043E\u0433\u0434\u0430 \u043A\u0430\u0440\u0442\u044B \u0432 \u0440\u0443\u043A\u0430\u0445 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u044E\u0442\u0441\u044F, \u043F\u043E\u0434\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0440\u0430\u0443\u043D\u0434\u0430. \u0412\u0442\u043E\u0440\u043E\u0439, \u0442\u0440\u0435\u0442\u0438\u0439 \u0438 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u044B\u0439 \u0440\u0430\u0443\u043D\u0434\u044B \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0440\u0430\u043D\u044C\u0448\u0435, \u043A\u0430\u043A \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u0437\u044F\u0442\u044B \u0432\u0441\u0435 \u043A\u0430\u0440\u0442\u044B, \u0437\u0430 \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0432 \u044D\u0442\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0435 \u043E\u0447\u043A\u0438.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 C \u0447\u0438\u0442\u0430\u0435\u0442 \u043A\u0430\u0440\u0442\u044B \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438, F \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442 \u043C\u0430\u0441\u0442\u044C \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0445\u043E\u0434\u0430, H \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0432\u043E\u044E \u0440\u0443\u043A\u0443. Z \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043A\u0430\u0440\u0442\u0443, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C; \u0435\u0441\u043B\u0438 \u0442\u0430\u043A\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0432\u0441\u0435\u0433\u043E \u043E\u0434\u043D\u0430, \u0441\u0440\u0430\u0437\u0443 \u0438\u0433\u0440\u0430\u0435\u0442 \u0435\u0451."),
            rule_section(:rounds, "\u0428\u0435\u0441\u0442\u044C \u0440\u0430\u0443\u043D\u0434\u043E\u0432",
              "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u043F\u0430\u0440\u0442\u0438\u0438 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u043E \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u0448\u0442\u0440\u0430\u0444\u043D\u0430\u044F \u043C\u0430\u0441\u0442\u044C, \u0432\u0438\u0434 \u0444\u0438\u0433\u0443\u0440\u044B \u0438 \u043E\u0434\u043D\u0430 \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430. \u042D\u0442\u043E\u0442 \u0432\u044B\u0431\u043E\u0440 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0432\u0441\u044E \u043F\u0430\u0440\u0442\u0438\u044E. \u041F\u0435\u0440\u0435\u0434 \u043A\u0430\u0436\u0434\u044B\u043C \u0440\u0430\u0443\u043D\u0434\u043E\u043C \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0435\u0433\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430 \u043E\u0447\u043A\u043E\u0432. \u041D\u0430\u0436\u043C\u0438 R, \u0447\u0442\u043E\u0431\u044B \u0443\u0441\u043B\u044B\u0448\u0430\u0442\u044C \u0438\u0445 \u0441\u043D\u043E\u0432\u0430; \u043A\u043B\u0430\u0432\u0438\u0448\u0430 V \u0442\u043E\u0436\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442.",
              "- \u0412 \u043F\u0435\u0440\u0432\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u043A\u0430\u0436\u0434\u0430\u044F \u0432\u0437\u044F\u0442\u043A\u0430 \u0441\u0442\u043E\u0438\u0442 5 \u0448\u0442\u0440\u0430\u0444\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0412\u043E \u0432\u0442\u043E\u0440\u043E\u043C \u043A\u0430\u0436\u0434\u0430\u044F \u0432\u0437\u044F\u0442\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0441\u0442\u043E\u0438\u0442 10 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0412 \u0442\u0440\u0435\u0442\u044C\u0435\u043C \u043A\u0430\u0436\u0434\u0430\u044F \u0444\u0438\u0433\u0443\u0440\u0430 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0432\u0438\u0434\u0430 \u2014 \u0432\u0430\u043B\u0435\u0442, \u0434\u0430\u043C\u0430 \u0438\u043B\u0438 \u043A\u043E\u0440\u043E\u043B\u044C \u2014 \u0441\u0442\u043E\u0438\u0442 50 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0412 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u043E\u043C \u0432\u0437\u044F\u0442\u0438\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0441\u0442\u043E\u0438\u0442 200 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0412 \u043F\u044F\u0442\u043E\u043C \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442 \u0432\u0441\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0448\u0442\u0440\u0430\u0444\u0430. \u041E\u0434\u043D\u0430 \u043A\u0430\u0440\u0442\u0430 \u043C\u043E\u0436\u0435\u0442 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0442\u044C\u0441\u044F \u0441\u0440\u0430\u0437\u0443 \u0432 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u0445.",
              "- \u0412 \u0448\u0435\u0441\u0442\u043E\u043C \u0442\u0435 \u0436\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0432\u044B\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u0438\u0437 \u043E\u0431\u0449\u0435\u0433\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0442\u0435\u043F\u0435\u0440\u044C \u043A\u0430\u0440\u0442\u044B \u0432\u044B\u0433\u043E\u0434\u043D\u043E \u0437\u0430\u0431\u0438\u0440\u0430\u0442\u044C.",
              "\u041A\u0430\u0440\u0442\u0443, \u043A\u043E\u0442\u043E\u0440\u0430\u044F \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0435 \u043E\u0447\u043A\u043E\u0432 \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u043C \u0440\u0430\u0443\u043D\u0434\u0435, \u043F\u0440\u0438 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0435 \u043E\u0442\u043C\u0435\u0447\u0430\u0435\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0437\u0432\u0443\u043A. \u0412\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0441\u0430\u043C\u044B\u0439 \u0432\u044B\u0441\u043E\u043A\u0438\u0439 \u0442\u043E\u043D, \u0444\u0438\u0433\u0443\u0440\u0435 \u2014 \u0431\u043E\u043B\u0435\u0435 \u043D\u0438\u0437\u043A\u0438\u0439, \u0430 \u043E\u0441\u043E\u0431\u043E\u0439 \u043A\u0430\u0440\u0442\u0435 \u0437\u0430 200 \u043E\u0447\u043A\u043E\u0432 \u2014 \u0441\u0430\u043C\u044B\u0439 \u043D\u0438\u0437\u043A\u0438\u0439."),
            rule_section(:scoring, "\u0412\u0441\u0451 \u0438\u043B\u0438 \u043D\u0438\u0447\u0435\u0433\u043E \u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u043F\u0430\u0440\u0442\u0438\u0438",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u00AB\u0412\u0441\u0451 \u0438\u043B\u0438 \u043D\u0438\u0447\u0435\u0433\u043E\u00BB. \u0415\u0441\u043B\u0438 \u0437\u0430 \u0440\u0430\u0443\u043D\u0434 \u0442\u044B \u0437\u0430\u0431\u0435\u0440\u0451\u0448\u044C \u0432\u0441\u0451, \u0437\u0430 \u0447\u0442\u043E \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u043E\u0447\u043A\u0438, \u0437\u043D\u0430\u043A \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F: \u0432\u043C\u0435\u0441\u0442\u043E \u0448\u0442\u0440\u0430\u0444\u0430 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0441\u044F \u0432\u044B\u0447\u0435\u0442. \u0412 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u044D\u0442\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u043D\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442.",
              "\u0412 \u043F\u0435\u0440\u0432\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435 \u043D\u0443\u0436\u043D\u044B \u0432\u0441\u0435 \u0432\u0437\u044F\u0442\u043A\u0438, \u0432\u043E \u0432\u0442\u043E\u0440\u043E\u043C \u2014 \u0432\u0441\u0435 \u043A\u0430\u0440\u0442\u044B \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438, \u0432 \u0442\u0440\u0435\u0442\u044C\u0435\u043C \u2014 \u0432\u0441\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0444\u0438\u0433\u0443\u0440\u044B \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0432\u0438\u0434\u0430. \u0412 \u043F\u044F\u0442\u043E\u043C \u0438 \u0448\u0435\u0441\u0442\u043E\u043C \u043D\u0443\u0436\u043D\u043E \u0432\u0437\u044F\u0442\u044C \u0432\u0441\u0435 \u0432\u0437\u044F\u0442\u043A\u0438. \u0412 \u0448\u0435\u0441\u0442\u043E\u043C \u0441\u043C\u0435\u043D\u0430 \u0437\u043D\u0430\u043A\u0430 \u043D\u0435\u0432\u044B\u0433\u043E\u0434\u043D\u0430: \u043E\u0447\u043A\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0434\u043E\u043B\u0436\u043D\u044B \u0431\u044B\u043B\u0438 \u0432\u044B\u0447\u0435\u0441\u0442\u044C, \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043A\u0430\u043A \u0448\u0442\u0440\u0430\u0444.",
              "\u041F\u043E\u0441\u043B\u0435 \u0448\u0435\u0441\u0442\u043E\u0433\u043E \u0440\u0430\u0443\u043D\u0434\u0430 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0438\u0433\u0440\u043E\u043A \u0441 \u043D\u0430\u0438\u043C\u0435\u043D\u044C\u0448\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439. \u0415\u0441\u043B\u0438 \u043D\u0430\u0438\u043C\u0435\u043D\u044C\u0448\u0438\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B \u0440\u0430\u0432\u043D\u044B, \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0438\u0447\u044C\u044F. S \u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0447\u0451\u0442. \u041F\u0440\u0430\u0432\u0438\u043B\u043E \u00AB\u0412\u0441\u0451 \u0438\u043B\u0438 \u043D\u0438\u0447\u0435\u0433\u043E\u00BB \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043A\u0430\u0440\u0442.",
              "Enter: \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0443\u044E \u043A\u0430\u0440\u0442\u0443.",
              "H: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u0440\u0443\u043A\u0443.",
              "C: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443.",
              "Ctrl+C: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0435\u0451 \u043A\u0430\u0440\u0442\u044B.",
              "F: \u043D\u0430\u043F\u043E\u043C\u043D\u0438\u0442\u044C \u043C\u0430\u0441\u0442\u044C \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0445\u043E\u0434\u0430.",
              "R / V: \u043D\u0430\u043F\u043E\u043C\u043D\u0438\u0442\u044C \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430 \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u043C \u0440\u0430\u0443\u043D\u0434\u0435.",
              "S: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0447\u0451\u0442.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0445\u043E\u0434.",
              "Z / Shift+Z: \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0430\u044F / \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0430\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430\u044F \u0434\u043B\u044F \u0445\u043E\u0434\u0430 \u043A\u0430\u0440\u0442\u0430.",
              "Shift+C: \u0441\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u043A\u0430 \u043F\u043E \u043C\u0430\u0441\u0442\u044F\u043C.",
              "Shift+H: \u0441\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u043A\u0430 \u043F\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0443.",
              "Shift+M: \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043A\u0430\u0440\u0442.")
          ]
        end
      end
